ids = ["LR3-002","LR3-004","LR3-006","LR3-008","LR3-010","LR3-101","LR3-104","LR3-107","LR3-110","LR3-112","LR3-114","LR3-116","LY-001","LY-002","LY-003","LY-004","LY-005","LY-006","LY-007","LY-008"]
assert set(P.keys()) == set(ids), (set(ids)-set(P.keys()))
for i in ids:
    d = {"case_id": i, **P[i]}
    (base / f"{i}.json").write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
# verify by exact list only
cnt = 0
for i in ids:
    p = base / f"{i}.json"
    assert p.exists(), i
    j = json.loads(p.read_text(encoding="utf-8"))
    assert j["case_id"] == i and j["prediction_text"] and j["basis"] and 0 <= j["confidence"] <= 1
    assert set(j["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    cnt += 1
assert cnt == len(ids) == 20
ly = [i for i in ids if i.startswith("LY-")]
print("written", cnt)
print("changed_main", sum(P[i]["trigger"]["changed_main"] for i in ly))
print("reserve_used", sum(P[i]["trigger"]["reserve_used"] for i in ly))
print("disputed", sum(P[i]["trigger"]["disputed"] for i in ly))
print("non-liuyao all false:", all(not P[i]["trigger"]["changed_main"] and not P[i]["trigger"]["reserve_used"] and not P[i]["trigger"]["disputed"] and P[i]["trigger"]["reason"]=="" for i in ids if not i.startswith("LY-")))
